def _normalize_model_id(model_id: str | None) -> str:
    """Reduce a raw model identifier to a readable name for the footer.

    Strips the Bedrock/region prefix (``us.anthropic.``) and any trailing
    version/revision suffix (``-v1:0``), so ``us.anthropic.claude-opus-4-8``
    becomes ``claude-opus-4-8``. A missing or ``None`` id (the documented
    "omit if unknown" case, which an LLM may express as an explicit JSON
    ``null``) yields an empty string.
    """
    name = (model_id or "").strip()
    if not name:
        return ""
    name = name.rsplit(".", 1)[-1]
    name = re.sub(r"-v\d+(:\d+)?$", "", name)
    return name


def _parse_paginated_json(stdout: str) -> list:
    """Parse gh api --paginate output which concatenates JSON arrays.

    When paginated, gh outputs ``[...][...]`` (multiple arrays back-to-back).
    Standard ``json.loads`` fails on this. We split on ``][`` boundaries and
    merge into a single list.
    """
    text = stdout.strip()
    if not text:
        return []
    try:
        result = json.loads(text)
        return result if isinstance(result, list) else [result]
    except (ValueError, TypeError):
        pass
    # Paginated concatenation: split on ][ boundary
    chunks = re.split(r'\]\s*\[', text)
    merged: list = []
    for i, chunk in enumerate(chunks):
        # Restore stripped brackets
        if i == 0:
            chunk = chunk + ']'
        elif i == len(chunks) - 1:
            chunk = '[' + chunk
        else:
            chunk = '[' + chunk + ']'
        try:
            merged.extend(json.loads(chunk))
        except (ValueError, TypeError):
            print(f"warning: _parse_paginated_json: failed to parse chunk {i}: "
                  f"{chunk[:100]!r}", file=sys.stderr)
            continue
    return merged


