_PR_URL_RE = re.compile(r'^[a-zA-Z0-9._-]+$')


def _parse_pr_url(pr_url: str) -> tuple[str, str, int]:
    """Extract and validate owner, repo, PR number from a GitHub PR URL.

    Raises ValueError on invalid or malformed URLs.
    """
    parsed = urlparse(pr_url)
    path_parts = parsed.path.strip("/").split("/")
    if len(path_parts) < 4:
        raise ValueError(f"Malformed PR URL (too few path segments): {pr_url}")
    owner, repo = path_parts[0], path_parts[1]
    if not _PR_URL_RE.match(owner):
        raise ValueError(f"Invalid owner in PR URL: {owner!r}")
    if not _PR_URL_RE.match(repo):
        raise ValueError(f"Invalid repo in PR URL: {repo!r}")
    try:
        number = int(path_parts[3])
    except (ValueError, IndexError):
        raise ValueError(f"Invalid PR number in URL: {pr_url}")
    if number <= 0:
        raise ValueError(f"PR number must be positive: {number}")
    return owner, repo, number


def _run_gh(*args: str, input_data: str | None = None) -> subprocess.CompletedProcess:
    """Run a gh CLI command and return the result."""
    result = subprocess.run(
        ["gh", *args],
        input=input_data,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0 and result.stderr:
        print(f"warning: gh {' '.join(args[:3])}: {result.stderr.strip()}", file=sys.stderr)
    return result


def run_preflight_checks(pr_url: str) -> dict:
    """Run pre-flight checks on a PR before reviewing.

    Returns a dict with:
      - merge_conflict: bool
      - stale: bool (no pushes in >14 days)
      - stale_days: int | None
      - self_review: bool (authenticated user is PR author)
      - author: str
      - current_user: str
      - warnings: list[str] (human-readable warning messages)
    """
    owner, repo, number = _parse_pr_url(pr_url)
    nwo = f"{owner}/{repo}"

    result = {
        "merge_conflict": False,
        "stale": False,
        "stale_days": None,
        "self_review": False,
        "author": "",
        "current_user": "",
        "warnings": [],
    }

    # Check mergeable status and author
    pr_info = _run_gh(
        "pr", "view", str(number), "--repo", nwo,
        "--json", "mergeable,author,updatedAt",
    )
    if pr_info.returncode == 0:
        try:
            info = json.loads(pr_info.stdout)
        except (json.JSONDecodeError, ValueError):
            info = {}
        result["author"] = info.get("author", {}).get("login", "")
        if info.get("mergeable") == "CONFLICTING":
            result["merge_conflict"] = True
            result["warnings"].append(
                "This PR has merge conflicts. Resolve conflicts before review findings are actionable."
            )
        updated = info.get("updatedAt", "")
        if updated:
            from datetime import datetime, timezone
            try:
                updated_dt = datetime.fromisoformat(updated.replace("Z", "+00:00"))
                days = (datetime.now(timezone.utc) - updated_dt).days
                if days > 14:
                    result["stale"] = True
                    result["stale_days"] = days
                    result["warnings"].append(
                        f"This PR has been inactive for {days} days."
                    )
            except (ValueError, TypeError):
                pass

    # Check current authenticated user
    user_info = _run_gh("api", "user", "--jq", ".login")
    if user_info.returncode == 0:
        result["current_user"] = user_info.stdout.strip()

    if result["current_user"] and result["author"]:
        if result["current_user"] == result["author"]:
            result["self_review"] = True
            result["warnings"].append(
                "Posted by PR author — self-reviews cannot apply the APPROVED label."
            )

    return result


def detect_previous_reviews(pr_url: str, current_user: str = "") -> dict:
    """Detect previous reviews by the same user on this PR.

    Returns a dict with:
      - previous_count: int (number of prior reviews by this user with our signature)
      - round_number: int (this review's round = previous_count + 1)
      - previous_findings: list[tuple[str, str]] (path, severity) from last review
      - last_review_sha: str | None (HEAD SHA from review-meta comment, if present)
      - last_review_submitted_at: str (ISO timestamp of last review, or "" if none)
    """
    result = {"previous_count": 0, "round_number": 1, "previous_findings": [], "last_review_sha": None}

    owner, repo, number = _parse_pr_url(pr_url)

    if not current_user:
        user_info = _run_gh("api", "user", "--jq", ".login")
        if user_info.returncode == 0:
            current_user = user_info.stdout.strip()
    if not current_user:
        return result

    # Fetch all reviews on this PR
    reviews_result = _run_gh(
        "api", f"repos/{owner}/{repo}/pulls/{number}/reviews",
        "--paginate",
    )
    if reviews_result.returncode != 0:
        return result

    reviews = _parse_paginated_json(reviews_result.stdout)
    if not reviews:
        return result

    # Filter for reviews by current user containing our signature
    signature = "Generated by"
    my_reviews = [
        r for r in reviews
        if r.get("user", {}).get("login") == current_user
        and signature in (r.get("body") or "")
    ]
    result["previous_count"] = len(my_reviews)
    result["round_number"] = len(my_reviews) + 1

    # Extract finding signatures and timestamp from the most recent previous review
    if my_reviews:
        last_review = my_reviews[-1]
        result["last_review_submitted_at"] = last_review.get("submitted_at", "")
        last_body = last_review.get("body", "")
        # Parse findings: look for patterns like (path:line) and severity labels
        for line in last_body.split("\n"):
            for sev in ("CRITICAL", "HIGH", "MEDIUM", "LOW"):
                if sev in line:
                    # Try to extract file path
                    path_match = re.search(r'`([^`]+?:\d+)`', line)
                    path = path_match.group(1).split(":")[0] if path_match else ""
                    result["previous_findings"].append((path, sev.lower()))
                    break
        # Parse review-meta for SHA
        meta = parse_review_meta(last_body)
        result["last_review_sha"] = meta["sha"] if meta else None

    return result


def should_recheck(pr_url: str, review_history: dict | None = None) -> dict:
    """Determine whether a PR needs a full review or just a recheck.

    Compares the volume of changes since the last review against thresholds.

    Returns a dict with:
      - mode: "full" | "recheck" | "first" (no previous review)
      - reason: str (human-readable explanation)
      - lines_changed: int (lines added+deleted since last review)
      - files_changed: int
      - new_files: list[str] (files not in the previous diff)
    """
    result = {
        "mode": "full",
        "reason": "No previous review found",
        "lines_changed": 0,
        "files_changed": 0,
        "new_files": [],
    }

    if not review_history or review_history.get("previous_count", 0) == 0:
        result["reason"] = "First review — running full review"
        return result

    last_submitted = review_history.get("last_review_submitted_at", "")
    if not last_submitted:
        result["reason"] = "Cannot determine last review time — running full review"
        return result

    # Get commits since last review
    owner, repo, number = _parse_pr_url(pr_url)
    nwo = f"{owner}/{repo}"

    commits_result = _run_gh(
        "pr", "view", str(number), "--repo", nwo,
        "--json", "commits",
    )
    if commits_result.returncode != 0:
        result["mode"] = "full"
        result["reason"] = "Cannot fetch commits — running full review"
        return result

    try:
        pr_data = json.loads(commits_result.stdout)
    except (ValueError, TypeError):
        result["mode"] = "full"
        result["reason"] = "Cannot parse commits — running full review"
        return result

    commits = pr_data.get("commits", [])
    # Find commits after the last review
    from datetime import datetime, timezone
    try:
        review_dt = datetime.fromisoformat(last_submitted.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        result["mode"] = "full"
        result["reason"] = "Cannot parse review timestamp — running full review"
        return result

    new_commits = []
    for c in commits:
        committed = c.get("committedDate", "") or c.get("authoredDate", "")
        if committed:
            try:
                commit_dt = datetime.fromisoformat(committed.replace("Z", "+00:00"))
                if commit_dt > review_dt:
                    new_commits.append(c)
            except (ValueError, TypeError):
                pass

    if not new_commits:
        result["mode"] = "recheck"
        result["reason"] = "No new commits since last review"
        return result

    # Sum additions/deletions from the new commits only (not the full PR diff)
    total_lines = 0
    files: set[str] = set()
    for c in new_commits:
        total_lines += c.get("additions", 0) + c.get("deletions", 0)
        for f in c.get("changedFiles", []):
            if isinstance(f, str):
                files.add(f)
            elif isinstance(f, dict):
                files.add(f.get("path", ""))

    # Fallback: if commit objects don't carry stats, use the full PR diff
    if total_lines == 0:
        diff_result = _run_gh("pr", "diff", str(number), "--repo", nwo)
        if diff_result.returncode == 0:
            for line in diff_result.stdout.split("\n"):
                if line.startswith("+++ b/"):
                    files.add(line[6:])
                elif line.startswith("+") and not line.startswith("+++"):
                    total_lines += 1
                elif line.startswith("-") and not line.startswith("---"):
                    total_lines += 1

    result["lines_changed"] = total_lines
    result["files_changed"] = len(files)

    # Previous finding files
    prev_files = {pf for pf, _ in review_history.get("previous_findings", [])}
    new_files = [f for f in files if f not in prev_files]
    result["new_files"] = new_files

    # Decision thresholds
    new_commit_count = len(new_commits)

    # Recheck if: few commits, small changes, no new files beyond what was reviewed
    if new_commit_count <= 5 and total_lines < 200 and len(new_files) <= 2:
        result["mode"] = "recheck"
        result["reason"] = (
            f"{new_commit_count} commit(s), {total_lines} lines changed, "
            f"{len(new_files)} new file(s) — likely fixing review findings"
        )
    else:
        result["mode"] = "full"
        result["reason"] = (
            f"{new_commit_count} commit(s), {total_lines} lines changed, "
            f"{len(new_files)} new file(s) — substantial changes since last review"
        )

    return result


