# Conflict classification patterns and their resolution strategies
_TRIVIAL_CONFLICT_PATTERNS: list[tuple[str, str]] = [
    (".claude-plugin/marketplace.json", "sync_marketplace"),
    ("AVAILABLE_SKILLS.md", "sync_skills"),
    ("uv.lock", "uv_lock"),
]

_TRIVIAL_CONFLICT_GLOBS: list[tuple[str, str]] = [
    (".github/ISSUE_TEMPLATE/*.yml", "sync_templates"),
    ("*/catalog-info.yaml", "catalog_info"),
]


def classify_conflicts(conflicting_files: list[str]) -> dict:
    """Classify conflicting files as trivial (auto-resolvable) or non-trivial.

    Returns:
        {"trivial": [...], "non_trivial": [...], "strategies": {file: strategy}}
    """
    trivial: list[str] = []
    non_trivial: list[str] = []
    strategies: dict[str, str] = {}

    for f in conflicting_files:
        matched = False
        for pattern, strategy in _TRIVIAL_CONFLICT_PATTERNS:
            if f == pattern:
                trivial.append(f)
                strategies[f] = strategy
                matched = True
                break
        if not matched:
            for glob_pattern, strategy in _TRIVIAL_CONFLICT_GLOBS:
                if fnmatch.fnmatch(f, glob_pattern):
                    trivial.append(f)
                    strategies[f] = strategy
                    matched = True
                    break
        if not matched:
            non_trivial.append(f)

    return {"trivial": trivial, "non_trivial": non_trivial, "strategies": strategies}


def fetch_acknowledged_findings(pr_url: str, current_user: str = "") -> set[tuple[str, str]]:
    """Fetch findings that have been acknowledged via reply comments.

    A finding is considered acknowledged if its inline review comment has a reply
    containing any of: thumbsup reaction, "acknowledged", "won't fix", "wontfix",
    "intentional", or "accepted".

    Returns a set of (path, severity) tuples for acknowledged findings.
    """
    owner, repo, number = _parse_pr_url(pr_url)

    if not current_user:
        user_info = _run_gh("api", "user", "--jq", ".login")
        if user_info.returncode == 0:
            current_user = user_info.stdout.strip()
    if not current_user:
        return set()

    # Fetch review comments (inline comments on diffs)
    comments_result = _run_gh(
        "api", f"repos/{owner}/{repo}/pulls/{number}/comments",
        "--paginate",
    )
    if comments_result.returncode != 0:
        return set()

    comments = _parse_paginated_json(comments_result.stdout)
    if not comments:
        return set()

    # Build a map of our inline comments by their id
    # Our comments contain severity labels and file paths
    our_comment_ids: dict[int, tuple[str, str]] = {}  # comment_id -> (path, severity)
    for c in comments:
        if c.get("user", {}).get("login") != current_user:
            continue
        body = c.get("body", "")
        path = c.get("path", "")
        # Extract severity from our formatted inline comments. Match both the
        # current Conventional Comments badge (`` `CRITICAL` ``) and the legacy
        # bold form (`**CRITICAL`) so replies to older reviews still resolve.
        for sev in ("CRITICAL", "HIGH", "MEDIUM", "LOW"):
            if f"`{sev}`" in body or f"**{sev}" in body:
                our_comment_ids[c["id"]] = (path, sev.lower())
                break

    if not our_comment_ids:
        return set()

    # Check for acknowledgment replies to our comments
    ack_keywords = {"acknowledged", "won't fix", "wontfix", "intentional", "accepted"}
    acknowledged: set[tuple[str, str]] = set()
    for c in comments:
        reply_to = c.get("in_reply_to_id")
        if reply_to and reply_to in our_comment_ids:
            reply_body = (c.get("body") or "").lower().strip()
            if any(kw in reply_body for kw in ack_keywords) or reply_body == "👍":
                acknowledged.add(our_comment_ids[reply_to])

    return acknowledged


_MAX_DIFF_CHARS = 10_000_000  # ~10 million characters (roughly 10 MB for ASCII diffs)


def _parse_diff_positions(diff_text: str) -> dict:
    """Parse a unified diff and return a map of (path, source_line) → position.

    The GitHub Review API 'position' is the 1-based line offset within the
    diff hunk for a given file.  We track the RIGHT side (new file) line
    numbers so that findings referencing current source lines can be mapped.

    Assumes standard ``git diff`` output with ``+++ b/`` path prefixes.
    Diffs from non-standard sources (e.g. ``git diff --no-index``) that omit
    the ``b/`` prefix will not have their paths extracted.
    """
    if len(diff_text) > _MAX_DIFF_CHARS:
        print("[review_formatter] Warning: diff too large, skipping position mapping", file=sys.stderr)
        return {}

    mapping: dict[tuple[str, int], int] = {}
    current_path: str | None = None
    position = 0
    right_line = 0

    for raw_line in diff_text.split("\n"):
        if raw_line.startswith("diff --git"):
            current_path = None
            position = 0
            continue
        if raw_line.startswith("+++ b/"):
            current_path = raw_line[6:]
            position = 0
            continue
        if raw_line.startswith("--- "):
            continue
        hunk_match = re.match(r'^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@', raw_line)
        if hunk_match:
            position += 1
            right_line = int(hunk_match.group(1))
            continue
        if current_path is None:
            continue
        if raw_line.startswith("+"):
            position += 1
            mapping[(current_path, right_line)] = position
            right_line += 1
        elif raw_line.startswith("-"):
            position += 1
        elif raw_line.startswith(" "):
            position += 1
            mapping[(current_path, right_line)] = position
            right_line += 1
        elif raw_line.startswith("\\"):
            pass  # "\ No newline at end of file" — not a position

    return mapping


def classify_ci_failure(log_text: str, check_name: str) -> dict:
    """Classify a CI failure log and determine if it's auto-fixable.

    Returns:
        {
            "auto_fixable": bool,
            "fix_type": str | None,  # lint, version_bump, sync_derived, formatting
            "severity": str,  # critical, high, medium, low, info
            "summary": str,
            "suggestion": str,
            "details": dict,  # fix-type-specific details
        }
    """
    result = {
        "auto_fixable": False,
        "fix_type": None,
        "severity": "medium",
        "summary": "",
        "suggestion": "",
        "details": {},
    }

    if not log_text.strip():
        result["summary"] = "Empty CI log"
        result["suggestion"] = "Re-run the CI check"
        return result

    lower = log_text.lower()

    # Infrastructure failures (timeouts, network) — highest priority
    if any(kw in lower for kw in ("timed out", "timeout", "connectionpool", "connectionerror")):
        result["severity"] = "info"
        result["summary"] = "Infrastructure failure (timeout/network)"
        result["suggestion"] = "Re-run the CI check \u2014 likely transient"
        return result

    # Lint failures
    if "lint-plugin" in lower or (check_name and "lint" in check_name.lower()):
        result["auto_fixable"] = True
        result["fix_type"] = "lint"
        result["summary"] = "Plugin lint check failed"
        result["suggestion"] = "Run lint-plugin.sh to see and fix errors"
        return result

    # Version bump
    version_match = re.search(r'version unchanged \(([^)]+)\)', log_text)
    if version_match or "version bump" in lower:
        plugin_match = re.search(r'plugins/([^/]+)', log_text)
        result["auto_fixable"] = True
        result["fix_type"] = "version_bump"
        result["summary"] = "Missing version bump"
        result["suggestion"] = "Bump patch version in plugin.json"
        result["details"] = {
            "current_version": version_match.group(1) if version_match else "",
            "plugin": plugin_match.group(1) if plugin_match else "",
        }
        return result

    # Derived file drift
    if any(kw in lower for kw in ("marketplace.json", "out of sync", "derived file")):
        result["auto_fixable"] = True
        result["fix_type"] = "sync_derived"
        result["summary"] = "Derived files out of sync"
        result["suggestion"] = "Run sync_derived_files.py"
        return result

    # Formatting (ruff, black, isort)
    if any(kw in lower for kw in ("ruff format", "black", "isort", "would reformat")):
        result["auto_fixable"] = True
        result["fix_type"] = "formatting"
        result["summary"] = "Code formatting issues"
        result["suggestion"] = "Run formatter (ruff format / black / isort)"
        return result

    # Test assertion failures (not auto-fixable, but provide suggestion)
    if "assertionerror" in lower or "assert " in lower:
        result["severity"] = "medium"
        result["summary"] = "Test assertion failure"
        result["suggestion"] = "Check if the expected value needs updating or if this is a regression"
        return result

    # Security failures
    if any(kw in lower for kw in ("security", "vulnerability", "cve")):
        result["severity"] = "high"
        result["summary"] = "Security check failure"
        result["suggestion"] = "Review security findings \u2014 never auto-fix"
        return result

    # Default
    result["summary"] = f"CI check '{check_name}' failed"
    result["suggestion"] = "Review the CI log for details"
    return result


_REVIEW_META_RE = re.compile(r'<!-- review-meta: ({.*?}) -->')


def emit_review_meta(sha: str, round_number: int, engine: str = "") -> str:
    """Generate a review-meta HTML comment for embedding in review body.

    The ``engine`` field records which code-review engine produced the review
    (e.g. ``review-toolkit``, ``review``). Downstream consumers (notably
    plugin-review's Step 1.5b engine-change detection) parse this field to
    decide whether to force a full review on baseline reset.
    """
    payload: dict = {"sha": sha, "round": round_number}
    if engine:
        payload["engine"] = engine
    data = json.dumps(payload)
    return f"<!-- review-meta: {data} -->"


def parse_review_meta(body: str) -> dict | None:
    """Extract review-meta from a review body. Returns None if not found."""
    match = _REVIEW_META_RE.search(body)
    if not match:
        return None
    try:
        return json.loads(match.group(1))
    except (json.JSONDecodeError, ValueError):
        return None


class ReviewFormatter:
    def __init__(self, data: dict):
        self.data = data
        self.pr_url = data.get("pr_url", "")
        self.recommendation = data.get("recommendation", "") or self._auto_recommendation()
        self.summary = data.get("summary", "") or data.get("rationale", "")
        self.required_actions = data.get("required_actions", [])
        self.optional_improvements = data.get("optional_improvements", [])
        self.sections = data.get("sections", [])
        self.metadata = data.get("review_metadata", {})
        self.preflight: dict | None = None
        self.review_history: dict | None = None
        self.acknowledged: set[tuple[str, str]] = set()

    def _auto_recommendation(self) -> str:
        """Derive recommendation from findings when not explicitly set."""
        max_sev = self._max_severity()
        if max_sev >= 3:  # critical or high
            return "REQUEST_CHANGES"
        if max_sev >= 2:  # medium
            return "APPROVE_WITH_SUGGESTIONS"
        return "APPROVE"

    def _max_severity(self) -> int:
        """Return the highest severity rank across all findings."""
        max_rank = 0
        for section in self.data.get("sections", []):
            for f in section.get("findings", []):
                rank = _SEVERITY_RANK.get(f.get("severity", ""), 0)
                if rank > max_rank:
                    max_rank = rank
        return max_rank

    def format_body(self) -> str:
        parts = []
        parts.append(self._format_summary())
        for section in self.sections:
            rendered = self._format_section(section)
            if rendered:
                parts.append(rendered)
        parts.append(self._format_footer())
        return "\n\n".join(parts)

    def _review_title(self) -> str:
        title = self.metadata.get("review_title", "")
        if not title:
            # Default to a generic "Review" heading rather than deriving a
            # (often verbose) title from the tool name — yields "## Review
            # Verdict: …". The tool name still appears in the footer.
            title = "Review"
        return title

    def _compute_review_delta(self) -> str:
        """Compare current findings against previous review findings."""
        if not self.review_history or not self.review_history.get("previous_findings"):
            return ""
        prev = set(self.review_history["previous_findings"])
        current: set[tuple[str, str]] = set()
        for section in self.sections:
            for f in section.get("findings", []):
                path = f.get("path", "")
                sev = f.get("severity", "")
                if path and sev:
                    current.add((path, sev))
        new_findings = current - prev
        resolved = prev - current
        # Only count acknowledged findings that were in both current and previous
        ack_count = len(current & prev & self.acknowledged) if self.acknowledged else 0
        parts = []
        if resolved:
            parts.append(f"{len(resolved)} resolved")
        if new_findings:
            parts.append(f"{len(new_findings)} new")
        unchanged = len(current & prev) - ack_count
        if unchanged > 0:
            parts.append(f"{unchanged} unchanged")
        if ack_count > 0:
            parts.append(f"{ack_count} acknowledged")
        if parts:
            return f"*Delta from previous review: {', '.join(parts)}*"
        return ""

    def _format_preflight_banners(self) -> str:
        """Format pre-flight check warnings as GitHub alert banners."""
        if not self.preflight:
            return ""
        lines = []
        pf = self.preflight
        if pf.get("merge_conflict"):
            lines.append("> [!CAUTION]")
            lines.append("> **Merge Conflicts Detected**")
            lines.append("> This PR has merge conflicts. Resolve conflicts before review findings are actionable.")
            lines.append("")
        if pf.get("self_review"):
            intended = RECOMMENDATION_DISPLAY.get(self.recommendation, self.recommendation)
            lines.append("> [!NOTE]")
            lines.append("> **Self-Review**")
            lines.append(f"> Posted by PR author (`{pf.get('current_user', '')}`) — self-reviews cannot apply the `APPROVED` label. Intended verdict: **{intended}**. Ask a teammate to run `plugin-review` for the `APPROVED` label.")
            lines.append("")
        if pf.get("stale"):
            lines.append("> [!WARNING]")
            lines.append(f"> **Stale PR** — inactive for {pf.get('stale_days', '?')} days.")
            lines.append("")
        return "\n".join(lines)

    def _format_summary(self) -> str:
        lines = []
        # Pre-flight banners go at the very top
        banners = self._format_preflight_banners()
        if banners:
            lines.append(banners)
        display_text = RECOMMENDATION_DISPLAY.get(
            self.recommendation, self.recommendation
        )
        title = self._review_title()
        round_suffix = ""
        if self.review_history and self.review_history.get("round_number", 1) > 1:
            round_suffix = f" (Round {self.review_history['round_number']})"
        if title:
            lines.append(f"## {title} Verdict: {display_text}{round_suffix}")
        else:
            lines.append(f"## Verdict: {display_text}{round_suffix}")
        # Delta summary from previous review
        if self.review_history and self.review_history.get("previous_count", 0) > 0:
            delta = self._compute_review_delta()
            if delta:
                lines.append("")
                lines.append(delta)
        if self.summary:
            for paragraph in self._split_summary(self.summary):
                lines.append("")
                lines.append(paragraph)
        if self.required_actions:
            lines.append("")
            lines.append("> [!WARNING]")
            lines.append("> **Required Actions**")
            for i, action in enumerate(self.required_actions, 1):
                lines.append(f"> {i}. {action}")
        if self.optional_improvements:
            lines.append("")
            lines.append("> [!NOTE]")
            lines.append("> **Suggestions**")
            for i, imp in enumerate(self.optional_improvements, 1):
                lines.append(f"> {i}. {imp}")
        lines.append("")
        lines.append("---")
        return "\n".join(lines)

    @staticmethod
    def _split_summary(text: str, target_sentences: int = 2) -> list[str]:
        """Split a summary into paragraphs of ~target_sentences each.

        If the text already contains paragraph breaks (double newlines),
        return those as-is. Otherwise, split on sentence boundaries.
        """
        if "\n\n" in text:
            return [p.strip() for p in text.split("\n\n") if p.strip()]
        sentences = re.split(r'(?<=[.!?])\s+', text.strip())
        if len(sentences) <= target_sentences:
            return [text.strip()]
        paragraphs = []
        for i in range(0, len(sentences), target_sentences):
            chunk = " ".join(sentences[i:i + target_sentences])
            if chunk:
                paragraphs.append(chunk)
        return paragraphs

    def _format_section(self, section: dict) -> str | None:
        body = section.get("body", "")
        # Add ALL findings to the section body (both inline and non-inline)
        findings_text = self._format_all_findings(section)
        if findings_text:
            body = f"{body}\n\n{findings_text}" if body else findings_text
        # Inject icons into table cells for ecosystem compliance tables
        body = self._inject_table_icons(body)
        if not body.strip():
            return None
        title = section.get("title", "Section")
        icon_key = section.get("icon", "")
        # Explicit `icon` keys win; otherwise derive a distinct, relevant icon
        # from the section title so each category isn't the generic :memo:.
        if icon_key and icon_key in SECTION_ICONS:
            icon = SECTION_ICONS[icon_key]
        else:
            icon = self._auto_section_icon(title)
        status_key = section.get("status", "") or self._auto_section_status(section)
        status_icon = SECTION_STATUS_ICONS.get(status_key, "")
        summary_line = section.get("summary_line", "")
        summary_text = f"{icon} {title}"
        if summary_line:
            summary_text += f" — {summary_line}"
        if status_icon:
            summary_text += f" {status_icon}"
        return (
            f"<details>\n<summary><h3>{summary_text}</h3></summary>\n\n"
            f"{body}\n\n</details>"
        )

    @staticmethod
    def _auto_section_icon(title: str) -> str:
        """Pick a relevant emoji for a section from its title.

        Explicit `icon` keys (mapped via SECTION_ICONS) take precedence; this
        is the fallback so each review category renders a distinct, meaningful
        icon (Change → :mag:, Code Review → :bug:, Test → :test_tube:, etc.)
        instead of the generic :memo:.
        """
        t = (title or "").casefold()
        for keyword, icon in _SECTION_TITLE_ICONS:
            if keyword in t:
                return icon
        return DEFAULT_SECTION_ICON

    @staticmethod
    def _auto_section_status(section: dict) -> str:
        """Derive section status from findings severity."""
        findings = section.get("findings", [])
        if not findings:
            return ""
        max_rank = 0
        for f in findings:
            rank = _SEVERITY_RANK.get(f.get("severity", ""), 0)
            if rank > max_rank:
                max_rank = rank
        if max_rank >= 3:  # critical or high
            return "fail"
        if max_rank >= 2:  # medium
            return "warn"
        if max_rank >= 1:  # low
            return "info"
        return "pass"

    @staticmethod
    def _inject_table_icons(body: str) -> str:
        """Replace bare PASS/WARN/FAIL in markdown table cells with icon versions."""
        if "|" not in body:
            return body
        lines = body.split("\n")
        result = []
        for line in lines:
            if "|" in line and "---" not in line:
                for status, replacement in _TABLE_STATUS_ICONS.items():
                    # Match status as a standalone word in table cells
                    line = re.sub(rf'\b{status}\b', replacement, line)
            result.append(line)
        return "\n".join(result)

    def _format_all_findings(self, section: dict) -> str:
        """Format ALL findings for the section body with severity icons."""
        findings = section.get("findings", [])
        if not findings:
            return ""
        lines = ["### Findings\n"]
        for f in findings:
            sev_key = f.get("severity", "")
            sev = SEVERITY_LABELS.get(sev_key, "")
            icon = SEVERITY_ICONS.get(sev_key, "")
            title = f.get("title", "")
            path = f.get("path", "")
            line_num = f.get("line", "")
            # Check if this finding was acknowledged
            is_acked = (path, sev_key) in self.acknowledged if self.acknowledged else False
            # Build the finding line, led by the Conventional Comments label.
            cc = conventional_prefix(f)
            subject = title or sev or "comment"
            prefix = f"{icon} **{cc}:** {subject}".strip()
            if sev and subject != sev:
                prefix += f" `{sev}`"
            if is_acked:
                prefix = f"~~{prefix}~~ *(acknowledged)*"
            # Add file location if available
            if path and line_num:
                location = f" (`{path}:{line_num}`)"
            elif path:
                location = f" (`{path}`)"
            else:
                location = ""
            body_text = f.get("body", "") or f.get("message", "")
            lines.append(f"- {prefix}{location}")
            if body_text:
                lines.append(f"  {body_text}")
            if f.get("suggestion"):
                lines.append(f"  **Suggestion:** {f['suggestion']}")
        return "\n".join(lines)

    def extract_inline_comments(self, diff_map: dict | None = None) -> list[dict]:
        """Extract inline comments from findings.

        If diff_map is provided, only include findings whose (path, line) appears
        in the diff, and use the diff hunk position instead of the source line.
        diff_map format: {(path, source_line): position}

        Note: when diff_map is used, ``side`` and ``start_line`` fields are
        intentionally omitted because position-based comments encode the diff
        side implicitly.  Multi-line ranges (start_line) are not supported in
        position mode by the GitHub Review API.
        """
        comments = []
        self._filtered_inline_count = 0
        for section in self.sections:
            for finding in section.get("findings", []):
                path = finding.get("path")
                line = finding.get("line")
                if not path or not line:
                    continue
                try:
                    line_int = int(line)
                except (ValueError, TypeError):
                    continue
                if diff_map is not None:
                    position = diff_map.get((path, line_int))
                    if position is None:
                        self._filtered_inline_count += 1
                        continue  # Finding stays in body summary, just not posted inline
                    comment = {"path": path, "position": position}
                else:
                    comment = {"path": path, "line": line_int}
                    if finding.get("side"):
                        comment["side"] = finding["side"]
                    if finding.get("start_line"):
                        comment["start_line"] = finding["start_line"]
                comment["body"] = self._format_inline_body(finding)
                comments.append(comment)
        return comments

    def _format_inline_body(self, finding: dict) -> str:
        # Conventional Comments header: `**label (decoration):** subject`, with
        # the severity kept as a trailing badge for at-a-glance triage.
        sev_key = finding.get("severity", "")
        sev = SEVERITY_LABELS.get(sev_key, "")
        alert = SEVERITY_ALERT.get(sev_key, "")
        title = finding.get("title", "")
        body_text = finding.get("body", "") or finding.get("message", "")
        prefix = conventional_prefix(finding)
        subject = title or sev or "comment"
        header = f"**{prefix}:** {subject}"
        if sev and subject != sev:
            header += f" `{sev}`"
        lines = []
        if alert:
            lines.append(f"> [!{alert}]")
            lines.append(f"> {header}")
        else:
            lines.append(header)
        if body_text:
            lines.append("")
            lines.append(body_text)
        if finding.get("suggestion"):
            lines.append("")
            lines.append(f"**Suggestion:** {finding['suggestion']}")
        return "\n".join(lines)

    def build_api_payload(self, diff_map: dict | None = None) -> dict:
        event = EVENT_MAP.get(self.recommendation, "COMMENT")
        # GitHub rejects APPROVE / REQUEST_CHANGES review *events* on the
        # author's own PR with HTTP 422 ("Can not request changes on your own
        # pull request"). For a self-review, downgrade the API event to COMMENT
        # — the verdict is still conveyed by the BLOCKED label (apply_labels)
        # and the self-review banner, so no signal is lost. Only applies when
        # preflight has run and flagged self_review; standalone/dry-run callers
        # (preflight is None) keep the mapped event.
        if self.preflight and self.preflight.get("self_review") and event != "COMMENT":
            event = "COMMENT"
        payload = {
            "body": self.format_body(),
            "event": event,
        }
        comments = self.extract_inline_comments(diff_map=diff_map)
        if comments:
            payload["comments"] = comments
        return payload

    def _format_footer(self) -> str:
        name = self.metadata.get("tool_name", "review-formatter")
        version = self.metadata.get("tool_version", "")
        date = self.metadata.get("review_date", "")
        stages = self.metadata.get("stages", [])
        model = _normalize_model_id(self.metadata.get("model", ""))
        label = f"{name}"
        if version:
            label += f" v{version}"
        if model:
            label += f" | {model}"
        if stages:
            label += f" | {', '.join(stages)}"
        if date:
            label += f" | {date[:10]}"
        filtered = getattr(self, "_filtered_inline_count", 0)
        if filtered:
            label += f" | {filtered} finding(s) moved to body-only (outside diff range)"
        parts = []
        # Emit a stages-executed block: compare expected vs actual stages.
        # If a declared stage produced no matching section, call it out loudly.
        stages_block = self._format_stages_executed()
        if stages_block:
            parts.append(stages_block)
        # Emit review-meta if head_sha is available
        head_sha = self.metadata.get("head_sha", "")
        if head_sha:
            round_num = self.review_history.get("round_number", 1) if self.review_history else 1
            # Record which engine produced this review so Step 1.5b in
            # plugin-review can detect engine changes and force full mode.
            engine = self.metadata.get("engine", "")
            parts.append(emit_review_meta(sha=head_sha, round_number=round_num, engine=engine))
        parts.append(f"<sub>Generated by {label}</sub>")
        return "\n".join(parts)

    def _format_stages_executed(self) -> str:
        """Render a 'Review Stages Executed' block that loudly marks missing stages.

        A stage is declared via `review_metadata.stages`. It is considered
        executed if a section with a matching title exists in `sections[]`.
        Missing declared stages are rendered as ❌ MISSING so reviewers and
        approvers see the gap — preventing silent skips of required stages
        (notably Policy Compliance Review).

        Matching is whitespace- and case-insensitive (titles are normalized
        via strip/collapse + casefold on both sides) so minor drift between
        the declared stage label and the section title does not cry wolf.
        """
        stages = self.metadata.get("stages", [])
        if not stages:
            return ""

        def _normalize(title: str) -> str:
            return " ".join(title.split()).casefold() if title else ""

        # Drop sections with empty/whitespace-only titles: an empty title
        # normalizes to "" and would prefix-match *every* declared stage
        # (since "".startswith("") and x.startswith("") are always True),
        # producing false "executed" marks and masking genuinely missing stages.
        normalized_titles = [
            norm for s in self.sections if (norm := _normalize(s.get("title", "")))
        ]

        def _stage_matched(stage_norm: str) -> bool:
            # A declared stage with an empty title can never be matched.
            if not stage_norm:
                return False
            return any(
                t == stage_norm or t.startswith(stage_norm) or stage_norm.startswith(t)
                for t in normalized_titles
            )

        lines = ["### Review Stages Executed", ""]
        any_missing = False
        for stage in stages:
            if _stage_matched(_normalize(stage)):
                lines.append(f"- :white_check_mark: {stage}")
            else:
                any_missing = True
                lines.append(
                    f"- :x: **{stage} — MISSING**  "
                    f"*(this stage was declared but produced no section; review is incomplete)*"
                )
        if any_missing:
            lines.insert(1, "> [!CAUTION]")
            lines.insert(2, "> One or more declared review stages did not run. This review is incomplete.")
            lines.insert(3, "")
        return "\n".join(lines)

    def parse_pr_url(self) -> tuple[str, str, int]:
        """Extract owner, repo, PR number from URL."""
        return _parse_pr_url(self.pr_url)

    def _fetch_diff_map(self, owner: str, repo: str, number: int) -> dict | None:
        """Fetch PR diff and build a map of (path, source_line) → diff position.

        Returns None if the diff cannot be fetched or parsed.
        """
        result = _run_gh(
            "api", f"repos/{owner}/{repo}/pulls/{number}",
            "-H", "Accept: application/vnd.github.v3.diff",
        )
        if result.returncode != 0:
            return None
        mapping = _parse_diff_positions(result.stdout)
        return mapping or None

    def _post_review(self, owner: str, repo: str, number: int, payload: dict) -> dict:
        """Post a review payload via gh api. Returns parsed response."""
        payload_json = json.dumps(payload)
        result = _run_gh(
            "api", "--method", "POST",
            f"repos/{owner}/{repo}/pulls/{number}/reviews",
            "--input", "-",
            input_data=payload_json,
        )
        if result.returncode != 0:
            raise RuntimeError(f"gh api failed: {result.stderr}")
        return json.loads(result.stdout)

    def apply_labels(self) -> bool:
        """Apply APPROVED/BLOCKED labels based on recommendation.

        Self-reviews can apply BLOCKED but never APPROVED — you cannot approve
        your own work. Returns True if labels were applied, False otherwise.
        """
        label_action = LABEL_MAP.get(self.recommendation)
        if not label_action or not self.pr_url:
            return False

        # Block self-approval: authors can BLOCK their own PR but not APPROVE it.
        # If preflight wasn't run, check directly rather than allowing bypass.
        if label_action["add"] == "APPROVED":
            is_self = self.preflight and self.preflight.get("self_review")
            if is_self:
                return False
            if not self.preflight:
                # Preflight not run — check self-review directly to prevent bypass
                user_info = _run_gh("api", "user", "--jq", ".login")
                if user_info.returncode == 0:
                    try:
                        owner, repo, number = self.parse_pr_url()
                    except (ValueError, IndexError):
                        return False
                    pr_info = _run_gh(
                        "pr", "view", str(number), "--repo", f"{owner}/{repo}",
                        "--json", "author", "--jq", ".author.login",
                    )
                    if pr_info.returncode == 0:
                        if user_info.stdout.strip() == pr_info.stdout.strip():
                            return False

        try:
            owner, repo, number = self.parse_pr_url()
        except (IndexError, ValueError):
            return False
        result = _run_gh(
            "pr", "edit", str(number), "--repo", f"{owner}/{repo}",
            "--add-label", label_action["add"],
            "--remove-label", label_action["remove"],
        )
        return result.returncode == 0

    def post(self, run_preflight: bool = True, apply_labels: bool = True) -> dict:
        """Post review via gh api. Returns API response.

        Fetches the PR diff to compute inline comment positions. If any inline
        comment fails validation (HTTP 422), retries without inline comments.
        """
        if run_preflight and self.pr_url:
            self.preflight = run_preflight_checks(self.pr_url)
            # Add merge conflict to required_actions if not already there
            if self.preflight.get("merge_conflict"):
                conflict_msg = "Resolve merge conflicts"
                if conflict_msg not in self.required_actions:
                    self.required_actions.append(conflict_msg)
            # Detect previous reviews for round counting and delta
            current_user = self.preflight.get("current_user", "")
            self.review_history = detect_previous_reviews(self.pr_url, current_user)
            # Fetch acknowledged findings (replies to our inline comments)
            if self.review_history and self.review_history.get("previous_count", 0) > 0:
                self.acknowledged = fetch_acknowledged_findings(self.pr_url, current_user)

        owner, repo, number = self.parse_pr_url()
        diff_map = self._fetch_diff_map(owner, repo, number)
        payload = self.build_api_payload(diff_map=diff_map)
        try:
            response = self._post_review(owner, repo, number, payload)
        except RuntimeError as exc:
            if "422" not in str(exc) or "comments" not in payload:
                raise
            n_dropped = len(payload["comments"])
            print(f"[review_formatter] Inline comments failed (422). "
                  f"Retrying without {n_dropped} inline comment(s).", file=sys.stderr)
            del payload["comments"]
            response = self._post_review(owner, repo, number, payload)

        # Apply labels regardless of review event (works even for self-reviews)
        if apply_labels:
            self.apply_labels()

        return response


def main():
    import argparse
    parser = argparse.ArgumentParser(description="Format and post PR reviews")
    parser.add_argument("--post", action="store_true", help="Post review to GitHub")
    parser.add_argument("--dry-run", action="store_true", help="Print payload (uses raw line numbers, not diff positions)")
    args = parser.parse_args()

    data = json.load(sys.stdin)
    formatter = ReviewFormatter(data)

    if args.dry_run:
        # Note: dry-run uses raw line numbers, not diff positions.
        # The --post path fetches the diff and converts to positions.
        payload = formatter.build_api_payload()
        print(json.dumps(payload, indent=2))
    elif args.post:
        result = formatter.post()
        print(json.dumps(result, indent=2))
    else:
        print(formatter.format_body())


if __name__ == "__main__":
    main()
